use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls").unwrap_or_default();
        let urls: Vec<String> = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();
        // Contract: present(urls). Producing no subscriptions would violate it,
        // so fail rather than emit an empty list.
        if urls.is_empty() {
            panic!("no subscriptions found in state");
        }
        SubscriptionList { urls }
    }
}

export!(Node);
