use crate::aap::caps::state_read;

struct Node;

fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('[') {
        // Crude JSON array of strings: extract the quoted elements.
        let mut out = Vec::new();
        let mut cur = String::new();
        let mut in_str = false;
        let mut esc = false;
        for c in trimmed.chars() {
            if in_str {
                if esc {
                    cur.push(c);
                    esc = false;
                } else if c == '\\' {
                    esc = true;
                } else if c == '"' {
                    in_str = false;
                    if !cur.is_empty() {
                        out.push(core::mem::take(&mut cur));
                    }
                    cur.clear();
                } else {
                    cur.push(c);
                }
            } else if c == '"' {
                in_str = true;
            }
        }
        return out;
    }
    trimmed
        .split_whitespace()
        .map(|l| l.to_string())
        .filter(|l| !l.is_empty())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // An absent or empty store yields an empty (but present) list;
        // the node must never trap on that input.
        let raw = state_read::get("subscriptions")
            .or_else(|| state_read::get("urls"))
            .unwrap_or_default();
        SubscriptionList { urls: parse_urls(&raw) }
    }
}

export!(Node);
